<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';

$user=fleet_cert_require_user();
fleet_cert_require_same_origin_post();
$in=json_decode((string)file_get_contents('php://input'),true);
if(!is_array($in))json_response(['ok'=>false,'message'=>'Invalid operations request.'],400);
$incomingAction=(string)($in['action']??'');
if($incomingAction==='decide_request')fleet_cert_require_permission($user,'operations.approve');
elseif($incomingAction==='decide_readiness')fleet_cert_require_permission($user,'readiness.approve');
elseif($incomingAction==='request_readiness')fleet_cert_require_permission($user,'readiness.request');
elseif(str_starts_with($incomingAction,'request_'))fleet_cert_require_permission($user,'operations.request');
else fleet_cert_require_permission($user,'operations.manage');
$db=fleet_db();$actor=(int)$user['id'];

function op_text(array $in,string $key,int $max,bool $required=false): string
{
    $value=trim((string)($in[$key]??''));
    if($required&&$value==='')throw new InvalidArgumentException('Complete all required fields.');
    if(mb_strlen($value)>$max)throw new InvalidArgumentException('One of the entered values is too long.');
    return $value;
}
function op_date(string $value): string
{
    if($value==='')return date('Y-m-d H:i:s');
    $date=DateTimeImmutable::createFromFormat('Y-m-d\\TH:i',$value)?:DateTimeImmutable::createFromFormat('Y-m-d H:i:s',$value);
    if(!$date)throw new InvalidArgumentException('Enter a valid effective date and time.');
    return $date->format('Y-m-d H:i:s');
}
function op_not_future(string $value): void
{
    if($value>date('Y-m-d H:i:s'))throw new InvalidArgumentException('Effective dates in FleetDesk cannot be in the future.');
}
function op_norm(string $value): string{return preg_replace('/[^A-Z0-9]/','',strtoupper($value))??'';}
function op_assert_no_duplicate_pending(PDO $db,string $actionType,?int $assetId,array $payload,array $previous): void
{
    $q=$db->query("SELECT request_number,action_type,payload_json,previous_json FROM operation_change_requests WHERE request_status='PENDING' FOR UPDATE");
    $target=(int)($payload['id']??$payload['asset_id']??$payload['assignment_id']??$payload['attachment_id']??$assetId??0);
    $head=(int)($payload['head_asset_id']??$previous['head_asset_id']??0);
    $trailer=(int)($payload['trailer_asset_id']??$previous['trailer_asset_id']??0);
    foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row){
        $pending=json_decode((string)$row['payload_json'],true)?:[];$old=json_decode((string)$row['previous_json'],true)?:[];
        $pendingAction=(string)($pending['action']??strtolower($row['action_type']));
        $pendingHead=(int)($pending['head_asset_id']??$old['head_asset_id']??0);$pendingTrailer=(int)($pending['trailer_asset_id']??$old['trailer_asset_id']??0);
        if(in_array($actionType,['LINK_TRAILER','UNLINK_TRAILER'],true)&&in_array($row['action_type'],['LINK_TRAILER','UNLINK_TRAILER'],true)&&(($head&&($head===$pendingHead||$head===$pendingTrailer))||($trailer&&($trailer===$pendingHead||$trailer===$pendingTrailer))))
            throw new InvalidArgumentException('A link or unlink request involving this Horse or Trailer is already pending approval. Wait for the reviewer to decide it.');
        $assetActions=['SAVE_ASSET','SET_LOCATION','SET_STATUS','ARCHIVE_ASSET','ASSIGN_DRIVER','END_DRIVER','LINK_TRAILER','UNLINK_TRAILER'];
        if($assetId&&in_array($actionType,$assetActions,true)&&in_array($row['action_type'],$assetActions,true)&&(int)($row['asset_id']??0)===$assetId)
            throw new InvalidArgumentException('Request '.$row['request_number'].' already has this asset under review. Wait for its decision before submitting another asset request.');
        if($actionType==='ASSIGN_DRIVER'&&$row['action_type']==='ASSIGN_DRIVER'&&(int)($pending['driver_id']??0)===(int)($payload['driver_id']??0))
            throw new InvalidArgumentException('A request to assign this driver is already pending approval. Wait for its decision first.');
        if($row['action_type']!==$actionType)continue;
        $pendingTarget=(int)($pending['id']??$pending['asset_id']??$pending['assignment_id']??$pending['attachment_id']??$old['id']??$old['asset_id']??$old['assignment_id']??$old['attachment_id']??0);
        $sameTarget=$target>0&&$target===$pendingTarget;
        if(!$sameTarget&&$target===0&&$pendingTarget===0){
            if($actionType==='SAVE_ASSET'){$left=op_norm((string)($payload['primary_identifier']??''));$right=op_norm((string)($pending['primary_identifier']??''));$sameTarget=$left!==''&&$left===$right;}
            elseif($actionType==='SAVE_YARD'){$key=trim((string)($payload['yard_code']??''))!==''?'yard_code':'yard_name';$left=op_norm((string)($payload[$key]??''));$right=op_norm((string)($pending[$key]??''));$sameTarget=$left!==''&&$left===$right;}
            elseif($actionType==='SAVE_DRIVER'){$left=op_norm((string)($payload['full_name']??''));$right=op_norm((string)($pending['full_name']??''));$sameTarget=$left!==''&&$left===$right;$phone=op_norm((string)($payload['phone']??''));$pendingPhone=op_norm((string)($pending['phone']??''));if($phone!==''&&$pendingPhone!=='')$sameTarget=$sameTarget&&$phone===$pendingPhone;}
        }
        if($sameTarget)throw new InvalidArgumentException('Request '.$row['request_number'].' for this item or change is already pending approval. Wait for the reviewer to decide it.');
    }
}
function op_asset(PDO $db,int $id,bool $lock=false): array
{
    $q=$db->prepare('SELECT id,primary_identifier,asset_type_id,current_yard_id,current_status_id,registration_status,make,model,manufacture_year,is_active FROM assets WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$a=$q->fetch();if(!$a)throw new InvalidArgumentException('The selected asset was not found.');return $a;
}
function op_asset_history(PDO $db,int $assetId,string $field,mixed $old,mixed $new,int $actor): void
{
    if($old===$new)return;
    $oldJson=$old===null?null:json_encode($old,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$newJson=$new===null?null:json_encode($new,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
    $q=$db->prepare("INSERT INTO asset_change_history(asset_id,sync_run_id,source_row_id,reconciliation_case_id,field_name,old_value,new_value,change_origin,changed_at,changed_by) VALUES(?,NULL,NULL,NULL,?,?,?,'HUMAN_REVIEW',NOW(),?)");$q->execute([$assetId,$field,$oldJson,$newJson,$actor]);
}
function op_identifier_available(PDO $db,string $norm,int $ignoreId=0): void
{
    $q=$db->query('SELECT id,primary_identifier FROM assets WHERE primary_identifier IS NOT NULL');
    foreach($q as $row){if((int)$row['id']!==$ignoreId&&op_norm((string)$row['primary_identifier'])===$norm)throw new InvalidArgumentException('That asset identifier is already registered.');}
    $q=$db->prepare('SELECT asset_id FROM asset_identifiers WHERE normalized_value=? AND asset_id<>? LIMIT 1');$q->execute([$norm,$ignoreId]);if($q->fetchColumn())throw new InvalidArgumentException('That identifier is already recorded as another asset identifier.');
}
function op_identifier(PDO $db,int $assetId,string $identifier,string $note='FleetDesk operational entry'): void
{
    $norm=op_norm($identifier);if($norm==='')return;
    $q=$db->prepare('UPDATE asset_identifiers SET is_primary=0 WHERE asset_id=? AND is_primary=1');$q->execute([$assetId]);
    $q=$db->prepare('SELECT id FROM asset_identifiers WHERE asset_id=? AND normalized_value=? LIMIT 1');$q->execute([$assetId,$norm]);$existing=$q->fetchColumn();
    if($existing){$q=$db->prepare('UPDATE asset_identifiers SET raw_value=?,is_primary=1,source_note=? WHERE id=?');$q->execute([$identifier,$note,(int)$existing]);}
    else{$q=$db->prepare('INSERT INTO asset_identifiers(asset_id,identifier_type,raw_value,normalized_value,is_primary,source_note) VALUES(?,?,?,?,1,?)');$q->execute([$assetId,'REGISTRATION',$identifier,$norm,$note]);}
}
function op_audit(PDO $db,int $actor,string $action,string $entity,int $id,string $description): void
{
    fleet_cert_log($db,$actor,$action,$entity,$id,$description);
}
function op_request(PDO $db,int $assetId,string $type,array $payload,array $previous,string $reason,int $actor): array
{
    $number='OP-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));
    $q=$db->prepare('INSERT INTO operation_change_requests(request_number,asset_id,action_type,payload_json,previous_json,request_reason,requested_by) VALUES(?,?,?,?,?,?,?)');
    $q->execute([$number,$assetId,$type,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),json_encode($previous,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),$reason?:null,$actor]);
    $id=(int)$db->lastInsertId();op_audit($db,$actor,'REQUEST','OPERATION_CHANGE_REQUEST',$id,'Submitted '.$type.' request '.$number.' for asset '.$assetId.'.');
    return ['id'=>$id,'number'=>$number];
}

try {
    $action=(string)($in['action']??'');
    $approvedRequestId=0;
    $approvalDecisionReason='';
    $db->beginTransaction();
    if($action==='request_readiness'){
        $horseId=(int)($in['horse_asset_id']??0);$trailerId=(int)($in['trailer_asset_id']??0);$driverId=(int)($in['driver_id']??0);$attachmentId=(int)($in['attachment_id']??0);$assignmentId=(int)($in['driver_assignment_id']??0);$horseCheck=(int)($in['horse_inspection_id']??0);$trailerCheck=(int)($in['trailer_inspection_id']??0);$fitnessId=(int)($in['driver_fitness_check_id']??0);
