        $q=$db->prepare("SELECT id FROM combination_readiness_approvals WHERE horse_asset_id=? AND trailer_asset_id=? AND driver_id=? AND status='PENDING' ORDER BY id DESC LIMIT 1 FOR UPDATE");$q->execute([$horseId,$trailerId,$driverId]);if($q->fetchColumn())throw new InvalidArgumentException('A readiness request for this Full Truck is already pending. Wait for the reviewer to decide it.');
        $q=$db->prepare('SELECT id FROM asset_attachments WHERE id=? AND head_asset_id=? AND trailer_asset_id=? AND attached_to IS NULL FOR UPDATE');$q->execute([$attachmentId,$horseId,$trailerId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The Horse and Trailer link is no longer active.');
        $q=$db->prepare('SELECT id FROM asset_driver_assignments WHERE id=? AND asset_id=? AND driver_id=? AND assigned_to IS NULL FOR UPDATE');$q->execute([$assignmentId,$horseId,$driverId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The driver assignment is no longer active.');
        $q=$db->prepare("SELECT id FROM vehicle_inspections WHERE id=? AND asset_id=? AND id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=?) AND result='PASS' AND critical_defects=0 AND checked_at>=NOW()-INTERVAL 24 HOUR FOR UPDATE");$q->execute([$horseCheck,$horseId,$horseId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The Horse needs a passing inspection from the last 24 hours.');
        if($trailerCheck){$q->execute([$trailerCheck,$trailerId,$trailerId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The Trailer needs a passing inspection from the last 24 hours.');}
        $q=$db->prepare("SELECT id FROM driver_fitness_checks WHERE id=? AND driver_id=? AND id=(SELECT MAX(id) FROM driver_fitness_checks WHERE driver_id=?) AND result='PASS' AND licence_checked=1 AND rested=1 AND fit_to_drive=1 AND licence_expiry IS NOT NULL AND licence_expiry>=CURDATE() AND checked_at>=NOW()-INTERVAL 24 HOUR FOR UPDATE");$q->execute([$fitnessId,$driverId,$driverId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The driver needs a passing fit-to-drive check from the last 24 hours, including licence, rest, and fitness confirmation.');
        $q=$db->prepare('SELECT COUNT(*) FROM maintenance_logs WHERE asset_id IN (?,?) AND resolved_at IS NULL');$q->execute([$horseId,$trailerId]);if((int)$q->fetchColumn()>0)throw new InvalidArgumentException('Resolve all open maintenance defects and re-inspect both units before requesting approval.');$q=$db->prepare("SELECT COUNT(*) FROM maintenance_work_orders WHERE asset_id IN (?,?) AND status IN ('OPEN','IN_PROGRESS','REPAIR_COMPLETE')");$q->execute([$horseId,$trailerId]);if((int)$q->fetchColumn()>0)throw new InvalidArgumentException('Close all repair work orders after successful re-inspection before requesting readiness approval.');
        $reason=op_text($in,'request_reason',500);$q=$db->prepare('INSERT INTO combination_readiness_approvals(horse_asset_id,trailer_asset_id,driver_id,attachment_id,driver_assignment_id,horse_inspection_id,trailer_inspection_id,driver_fitness_check_id,request_reason,requested_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$horseId,$trailerId,$driverId,$attachmentId,$assignmentId,$horseCheck,$trailerCheck?:null,$fitnessId,$reason?:null,$actor]);$id=(int)$db->lastInsertId();op_audit($db,$actor,'REQUEST','COMBINATION_READINESS',$id,'Requested readiness approval for Horse '.$horseId.', Trailer '.$trailerId.', driver '.$driverId.'.');$db->commit();json_response(['ok'=>true,'message'=>'Full Truck readiness submitted for reviewer approval.']);
    }
    if($action==='decide_readiness'){
        $id=(int)($in['request_id']??0);$decision=strtoupper(trim((string)($in['decision']??'')));$reason=op_text($in,'reason',500,$decision==='DECLINED');if(!$id||!in_array($decision,['APPROVED','DECLINED'],true))throw new InvalidArgumentException('Choose a valid readiness decision.');$q=$db->prepare('SELECT * FROM combination_readiness_approvals WHERE id=? FOR UPDATE');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['status']!=='PENDING')throw new InvalidArgumentException('This readiness request is no longer pending.');if((int)$r['requested_by']===$actor)throw new InvalidArgumentException('A different reviewer must approve this Full Truck.');
        if($decision==='APPROVED'){$q=$db->prepare('SELECT id FROM asset_attachments WHERE id=? AND head_asset_id=? AND trailer_asset_id=? AND attached_to IS NULL FOR UPDATE');$q->execute([(int)$r['attachment_id'],(int)$r['horse_asset_id'],(int)$r['trailer_asset_id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('The Horse and Trailer link changed. Refresh readiness and submit it again.');$q=$db->prepare('SELECT id FROM asset_driver_assignments WHERE id=? AND asset_id=? AND driver_id=? AND assigned_to IS NULL FOR UPDATE');$q->execute([(int)$r['driver_assignment_id'],(int)$r['horse_asset_id'],(int)$r['driver_id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('The driver assignment changed. Refresh readiness and submit it again.');$q=$db->prepare("SELECT id FROM vehicle_inspections WHERE id=? AND asset_id=? AND id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=?) AND result='PASS' AND critical_defects=0 AND checked_at>=NOW()-INTERVAL 24 HOUR FOR UPDATE");$q->execute([(int)$r['horse_inspection_id'],(int)$r['horse_asset_id'],(int)$r['horse_asset_id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('The Horse inspection is no longer current and valid.');if($r['trailer_inspection_id']){$q->execute([(int)$r['trailer_inspection_id'],(int)$r['trailer_asset_id'],(int)$r['trailer_asset_id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('The Trailer inspection is no longer current and valid.');}$q=$db->prepare("SELECT id FROM driver_fitness_checks WHERE id=? AND driver_id=? AND id=(SELECT MAX(id) FROM driver_fitness_checks WHERE driver_id=?) AND result='PASS' AND licence_checked=1 AND rested=1 AND fit_to_drive=1 AND licence_expiry IS NOT NULL AND licence_expiry>=CURDATE() AND checked_at>=NOW()-INTERVAL 24 HOUR FOR UPDATE");$q->execute([(int)$r['driver_fitness_check_id'],(int)$r['driver_id'],(int)$r['driver_id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('The driver fit-to-drive check is no longer current