        $q=$db->prepare('UPDATE combination_readiness_approvals SET status=?,decided_by=?,decided_at=NOW(),decision_reason=? WHERE id=? AND status=\'PENDING\'');$q->execute([$status,$actor,$reason?:null,$id]);op_audit($db,$actor,$decision,'COMBINATION_READINESS',$id,$decision==='APPROVED'?'Approved Full Truck readiness.':'Declined Full Truck readiness. '.$reason);$db->commit();json_response(['ok'=>true,'message'=>$decision==='APPROVED'?'Full Truck readiness approved.':'Readiness request declined.']);
    }
