        $decision=strtoupper(trim((string)($in['decision']??'')));
        $reason=op_text($in,'reason',500,$decision==='DECLINED');
        $approvalDecisionReason=$reason;
        if(!$requestId||!in_array($decision,['APPROVED','DECLINED'],true))throw new InvalidArgumentException('Choose a valid approval decision.');
        $q=$db->prepare('SELECT * FROM operation_change_requests WHERE id=? FOR UPDATE');$q->execute([(int)$requestId]);$request=$q->fetch();
        if(!$request||$request['request_status']!=='PENDING')throw new InvalidArgumentException('This request is no longer awaiting review.');
        if((int)$request['requested_by']===$actor)throw new InvalidArgumentException('A different reviewer must decide this request.');
        if($decision==='DECLINED'){$q=$db->prepare("UPDATE operation_change_requests SET request_status='DECLINED',decided_by=?,decided_at=NOW(),decision_reason=? WHERE id=?");$q->execute([$actor,$reason,(int)$requestId]);op_audit($db,$actor,'DECLINE','OPERATION_CHANGE_REQUEST',(int)$requestId,'Declined '.$request['request_number'].'. '.$reason);$db->commit();json_response(['ok'=>true,'message'=>'Request declined. No fleet data was changed.']);}
