        if($payload['action']==='save_yard'&&(int)($payload['id']??0)>0){$q=$db->prepare('SELECT id,yard_code,yard_name,location_description,is_active FROM yards WHERE id=? FOR UPDATE');$q->execute([(int)$payload['id']]);$current=$q->fetch();foreach($previous as $key=>$value)if((string)($current[$key]??'')!==(string)($value??''))throw new InvalidArgumentException('This location changed after the update request was submitted. Refresh and submit a new request.');}
