            $assetId=filter_var($in['id']??null,FILTER_VALIDATE_INT);if(!$assetId)throw new InvalidArgumentException('Select an asset.');$asset=op_asset($db,(int)$assetId,true);if(!(int)$asset['is_active'])throw new InvalidArgumentException('This asset is already archived.');$q=$db->prepare('UPDATE assets SET is_active=0,updated_at=NOW() WHERE id=?');$q->execute([(int)$assetId]);$q=$db->prepare('UPDATE asset_driver_assignments SET assigned_to=GREATEST(NOW(),assigned_from) WHERE asset_id=? AND assigned_to IS NULL');$q->execute([(int)$assetId]);$q=$db->prepare('UPDATE asset_yard_history SET valid_to=GREATEST(NOW(),valid_from) WHERE asset_id=? AND valid_to IS NULL');$q->execute([(int)$assetId]);op_asset_history($db,(int)$assetId,'is_active','1','0',$actor);op_audit($db,$actor,'ARCHIVE','ASSET',(int)$assetId,'Archived asset '.$asset['primary_identifier'].' in FleetDesk.');break;
        }
        default: throw new InvalidArgumentException('Choose a valid fleet operation.');
    }
    if($approvedRequestId){$q=$db->prepare("UPDATE operation_change_requests SET request_status='APPROVED',decided_by=?,decided_at=NOW(),decision_reason=? WHERE id=? AND request_status='PENDING'");$q->execute([$actor,$approvalDecisionReason?:null,$approvedRequestId]);if($q->rowCount()!==1)throw new InvalidArgumentException('This request was already decided.');op_audit($db,$actor,'APPROVE','OPERATION_CHANGE_REQUEST',$approvedRequestId,'Approved and applied operation request '.$approvedRequestId.'.'.($approvalDecisionReason?' '.$approvalDecisionReason:''));}
    $db->commit();
    json_response(['ok'=>true,'message'=>'Fleet operations change saved.']);
}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();json_response(['ok'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Fleet operations update: '.$e->getMessage());json_response(['ok'=>false,'message'=>'The fleet operations change could not be saved. No change was applied.'],500);}
